Here is the commit message:
netfilter: nfnetlink_hook: fix array index out-of-bounds
 error

Currently the array net->nf.hooks_ipv6 is accessed by index hook
before hook is sanity checked. Fix this by moving the sanity check
to before the array access.

Addresses-Coverity: ("Out-of-bounds access")
Fixes: e2cf17d3774c ("netfilter: add new hook nfnl subsystem")
Signed-off-by: Colin Ian King <colin.king@canonical.com>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

Here is the root cause:
The bug is caused by accessing the `net->nf.hooks_ipv6` array using the `hook` index without first verifying that the index is within valid bounds. If `hook` exceeds the size of the array, it results in an out-of-bounds access, which can lead to undefined behavior or crashes.

Here is the patch:

 static const struct nf_hook_entries *
 nfnl_hook_entries_head(u8 pf, unsigned int hook, struct net *net, const char *dev)
 {
 	const struct nf_hook_entries *hook_head = NULL;
 	struct net_device *netdev;

 	switch (pf) {
 	case NFPROTO_IPV4:
 		if (hook >= ARRAY_SIZE(net->nf.hooks_ipv4))
 			return ERR_PTR(-EINVAL);
 		hook_head = rcu_dereference(net->nf.hooks_ipv4[hook]);
 		break;
 	case NFPROTO_IPV6:
-		hook_head = rcu_dereference(net->nf.hooks_ipv6[hook]);
 		if (hook >= ARRAY_SIZE(net->nf.hooks_ipv6))
 			return ERR_PTR(-EINVAL);
+		hook_head = rcu_dereference(net->nf.hooks_ipv6[hook]);
 		break;
 	case NFPROTO_ARP:
 #ifdef CONFIG_NETFILTER_FAMILY_ARP
 		if (hook >= ARRAY_SIZE(net->nf.hooks_arp))
 			return ERR_PTR(-EINVAL);
 		hook_head = rcu_dereference(net->nf.hooks_arp[hook]);
 #endif
 		break;
 	case NFPROTO_BRIDGE:
 #ifdef CONFIG_NETFILTER_FAMILY_BRIDGE
 		if (hook >= ARRAY_SIZE(net->nf.hooks_bridge))
 			return ERR_PTR(-EINVAL);
 		hook_head = rcu_dereference(net->nf.hooks_bridge[hook]);
 #endif
 		break;
 #if IS_ENABLED(CONFIG_DECNET)
 	case NFPROTO_DECNET:
 		if (hook >= ARRAY_SIZE(net->nf.hooks_decnet))
 			return ERR_PTR(-EINVAL);
 		hook_head = rcu_dereference(net->nf.hooks_decnet[hook]);
 		break;
 #endif
 #ifdef CONFIG_NETFILTER_INGRESS
 	case NFPROTO_NETDEV:
 		if (hook != NF_NETDEV_INGRESS)
 			return ERR_PTR(-EOPNOTSUPP);

 		if (!dev)
 			return ERR_PTR(-ENODEV);

 		netdev = dev_get_by_name_rcu(net, dev);
 		if (!netdev)
 			return ERR_PTR(-ENODEV);

 		return rcu_dereference(netdev->nf_hooks_ingress);
 #endif
 	default:
 		return ERR_PTR(-EPROTONOSUPPORT);
 	}

 	return hook_head;
 }



